US_CSS = "\n:root{\n  --red:#ff4757;--up:#ff4757;--green:#00d4aa;--dn:#00d4aa;--flat:#b9c0cc;\n  --bg:#f4f6fa;--card:#ffffff;--line:#e3e8f0;\n  --txt:#1f2937;--sub:#6b7280;--muted:#9ca3af;\n  --blue:#1d4ed8;--blue-l:#eef2ff;--purple:#6d28d9;--purple-l:#f5f3ff;\n  --amber:#d97706;--amber-l:#fef3c7;--green-l:#ecfdf5;--green-d:#059669;\n  --grad:linear-gradient(135deg,#1e3a8a,#4f46e5 60%,#7c3aed);\n  --radius:14px;--radius-s:10px;\n  --shadow:0 1px 3px rgba(16,24,40,.05);\n}\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:var(--bg);color:var(--txt);font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",\"PingFang SC\",\"Microsoft YaHei\",sans-serif;line-height:1.6;padding:0 0 60px}\n.wrap{max-width:1000px;margin:0 auto;padding:0 20px}\nheader{background:var(--grad);color:#fff;padding:32px 0 26px;border-radius:0 0 24px 24px}\n.hd-in{max-width:1000px;margin:0 auto;padding:0 20px;display:flex;justify-content:space-between;align-items:flex-end;flex-wrap:wrap;gap:16px}\n.hd-tag{font-size:12px;letter-spacing:2px;opacity:.85;background:rgba(255,255,255,.15);display:inline-block;padding:4px 12px;border-radius:20px;margin-bottom:12px}\n.hd-in h1{font-size:26px;font-weight:700;letter-spacing:1px}\n.hd-date{font-size:13px;opacity:.9;margin-top:6px}\n.temp-badge{background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.35);border-radius:16px;padding:10px 20px;text-align:center;backdrop-filter:blur(4px)}\n.temp-num{font-size:32px;font-weight:700;line-height:1.1}\n.temp-lbl{font-size:12px;opacity:.9;margin-top:2px}\n.sub{font-size:12.5px;color:var(--muted);margin:18px 0 20px;display:flex;gap:10px;flex-wrap:wrap}\n.sub b{color:#5b6478}\n.card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:22px 24px;margin-bottom:18px;box-shadow:var(--shadow)}\n.card h2{font-size:16px;font-weight:700;margin-bottom:14px;display:flex;align-items:center;gap:8px}\n.card h2 .tag{font-size:11px;font-weight:700;color:#fff;background:var(--grad);padding:3px 9px;border-radius:7px;letter-spacing:1px}\n.up{color:var(--red)}.dn{color:var(--green)}.flat{color:var(--flat)}\n.grid{display:grid;gap:12px}\n.g3{grid-template-columns:repeat(3,1fr)}\n.g4{grid-template-columns:repeat(4,1fr)}\n@media(max-width:760px){.g3,.g4{grid-template-columns:1fr 1fr}}\n.vd-card{border-radius:12px;padding:14px 16px;background:var(--blue-l);border:1px solid #c7d7fe}\n.vd-card.hot{background:#fee2e2;border-color:#fecaca}\n.vd-card.blue{background:var(--blue-l);border-color:#c7d7fe}\n.vd-card.amber{background:var(--amber-l);border-color:#fde68a}\n.vd-card.green{background:var(--green-l);border-color:#a7f3d0}\n.vd-card.purple{background:var(--purple-l);border-color:#ddd6fe}\n.vd-t{font-size:13px;font-weight:700;margin-bottom:5px}\n.vd-d{font-size:12.5px;color:#4a5468}\n.kpi{display:flex;align-items:center;gap:10px;padding:12px 0;border-bottom:1px dashed var(--line)}\n.kpi:last-child{border-bottom:none}\n.kpi .nm{width:86px;font-size:12.5px;color:var(--sub);font-weight:600;flex-shrink:0}\n.kpi .bar{flex:1;height:8px;background:#eef0f5;border-radius:5px;overflow:hidden}\n.kpi .bar i{display:block;height:100%;border-radius:5px;background:var(--grad)}\n.kpi .bar i.warn{background:linear-gradient(90deg,#ffa502,#ff4757)}\n.kpi .val{font-size:13px;font-weight:700;min-width:160px;text-align:right}\n.tbl{width:100%;border-collapse:collapse;font-size:12.5px}\n.tbl th{background:#f5f6fa;color:#5b6478;font-weight:700;padding:8px 10px;text-align:right;border-bottom:2px solid var(--line);white-space:nowrap}\n.tbl th:first-child,.tbl td:first-child{text-align:left}\n.tbl td{padding:8px 10px;border-bottom:1px solid #f0f2f7;text-align:right;white-space:nowrap}\n.tbl tr:hover td{background:#fafbfe}\n.tbl .gp td{background:#f0f2f8;color:#5b6478;font-weight:800;font-size:12px;padding:6px 10px;text-align:left}\n.mini-bar{display:inline-block;width:52px;height:6px;background:#eef0f5;border-radius:3px;vertical-align:middle;margin-left:6px;overflow:hidden}\n.mini-bar i{display:block;height:100%;border-radius:3px}\n.flow-note{font-size:12px;color:var(--muted);margin-top:12px;line-height:1.9}\n.flow-note b{color:#5b6478}\ndetails.cat{margin-top:12px;border:1px solid var(--line);border-radius:var(--radius-s);background:#fafbfe;overflow:hidden}\ndetails.cat summary{cursor:pointer;padding:11px 16px;font-size:13px;font-weight:700;color:var(--blue);list-style:none;display:flex;align-items:center;gap:6px}\ndetails.cat summary::-webkit-details-marker{display:none}\ndetails.cat summary:before{content:\"\u25b8\";transition:transform .2s;color:var(--purple)}\ndetails.cat[open] summary:before{transform:rotate(90deg)}\ndetails.cat .inner{padding:4px 16px 14px;font-size:12.5px;color:#4a5468}\ndetails.cat .inner h4{font-size:12.5px;color:var(--txt);margin:10px 0 4px}\n.disc{background:#f9fafb;border:1px solid var(--line);border-radius:12px;padding:14px 20px;font-size:12px;color:var(--muted);margin-top:20px;line-height:1.8}\n.disc b{color:#6b7280}\n.temp-wrap{display:flex;align-items:center;gap:26px;flex-wrap:wrap}\n.temp-svg{flex-shrink:0}\n.temp-side{flex:1;min-width:280px}\n.temp-score{font-size:46px;font-weight:900;line-height:1}\n.temp-lbl{font-size:13px;color:var(--muted);margin-top:4px}\n.pill{display:inline-block;font-size:11px;font-weight:700;padding:2px 9px;border-radius:20px}\n.pill.r{background:#fee2e2;color:#dc2626}\n.pill.g{background:var(--green-l);color:var(--green-d)}\n.pill.b{background:var(--blue-l);color:var(--blue)}\n.pill.p{background:var(--purple-l);color:var(--purple)}\n.lk{font-size:12px;color:var(--blue);text-decoration:none;font-weight:700}\n.lk:hover{text-decoration:underline}\n.num-big{font-size:15px;font-weight:800}\n@media(max-width:760px){.hd-in{flex-direction:column;align-items:flex-start}.temp-badge{align-self:flex-start}}\n"
